WITH unpacked AS (SELECT id, coupon_codes, items, attributes, attributes['device'] AS device, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, SIZE(items) AS num_items, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, SIZE(attributes) AS num_attributes FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'SPRING10')) SELECT *, CUME_DIST() OVER (ORDER BY num_items DESC) AS num_items_cume_dist, LAG(bulk_lines, 2) OVER (ORDER BY num_attributes, id) AS prev_bulk_lines, AVG(bulk_lines) OVER (ORDER BY num_items, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS bulk_lines_avg_5 FROM unpacked;
